local CoWait = CS.Engine.Lib.CoWait
local util = require 'XLua.util'
local cs_coroutine = import('XLua.cs_coroutine')
local WaitForSeconds = CS.UnityEngine.WaitForSeconds

local UISwitchImage = CS.Game.Native.Common.UISwitchImage
local UISwitchText = CS.Game.Native.Common.UISwitchText
local KTool = CS.Engine.Lib.KTool
local UIModule = CS.Engine.UI.UIModule
local phoneComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)

---@class UIFeelingMainItemBtnNode
---@field ImgHead                       	UnityEngine.RectTransform               
---@field NewMessageNode                	UnityEngine.RectTransform               
---@field TitleText                     	UnityEngine.RectTransform               
---@field Icon                          	UnityEngine.RectTransform               
---@field ActiveNode                    	UnityEngine.RectTransform               
---@field ButtonBg                      	UnityEngine.RectTransform                          
local UIFeelingMainItemBtnNode = Class("UIFeelingMainItemBtnNode")
function UIFeelingMainItemBtnNode:__init() 
    self._data = nil
    self._clickCb = nil
end

function UIFeelingMainItemBtnNode:__delete()
    self._data = nil
    self._clickCb = nil
end

function UIFeelingMainItemBtnNode:Awake()
    SetButtonAction(self.controller, Bind(self, self.OnClick))
end

function UIFeelingMainItemBtnNode:Start()
end

function UIFeelingMainItemBtnNode:Refresh(data)
    if not data then
        return
    end
    self._data = data
    self._clickCb = self._data.fun

    self:FillSelf()
    KTool.SetActive(self.controller, true)
end

function UIFeelingMainItemBtnNode:FillSelf()
    GameUtils.RefeshSystemToggleId(self.controller, self._data.systemToggleId)
    local isUnlock = GameUtils.IsUnlockedBySystemTogId(self._data.systemToggleId)
    if self.ActiveNode then
        KTool.SetActive(self.ActiveNode, isUnlock)
    end
    local imgIndex = isUnlock and 1 or 2
    self.ButtonBg:GetComponent(typeof(UISwitchImage)).Status = imgIndex
    self.Icon:GetComponent(typeof(UISwitchImage)).Status = imgIndex
    self.TitleText.transform:GetComponent(typeof(UISwitchText)).Status = imgIndex
    self.Icon:GetComponent(typeof(UISwitchImage)):Reset()

    CfUtils.FillText(self.TitleText, self._data.name)
    CfUtils.FillImage(self.Icon, self._data.image)
    self:FillSpecialNode()

    self:RefeshRedPoint(self._data)
end

function UIFeelingMainItemBtnNode:FillSpecialNode()
    if self._data.systemToggleId == Constants.SystemToggleIds.Id221 then
        local t = GameUtils.GetRedPointLocalAllGoods(Constants.RedPointLocalKey.Goodkey, Constants.IDType.PhoneTalkContent)
        if table.count(t) > 0 then
            KTool.SetActive(self.NewMessageNode, true)
            KTool.SetActive(self.TitleText, false)

            local talkCountId = t[1]
            local vo = PhoneUtils.GetPhoneTalkContentVo(talkCountId)
            if vo then
                SetButtonAction(self.controller, function()
                    if GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id221) then
                        UIModule.OpenDialog({ id = Constants.UITypeIds.UIFeelingCommunicationDialog, parameters = {catId = vo.character}}, {
                            {id = Constants.UITypeIds.UIFeelingMainDialog}
                        })
                    else  
                        GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id221))  
                    end
                end)

                local skinCardId = PhoneUtils.GetRoleCurCardSkinId(vo.character) 
                local headPath =  CardConfMgr:GetInstance():GetCardDefaultSmallHeadPath(skinCardId)
                CfUtils.FillImage(self.ImgHead, headPath)
            end       
        end
    end
end

function UIFeelingMainItemBtnNode:RefeshRedPoint(data)
    if data.systemToggleId == Constants.SystemToggleIds.Id207 then
        GameUtils.BindRedPoint(Constants.RedPointConst.PhoneAchievement, self.controller, true)
    elseif data.systemToggleId == Constants.SystemToggleIds.Id222 then
        GameUtils.BindRedPoint(Constants.RedPointConst.PhoneReward, self.controller, true)
    elseif data.systemToggleId == Constants.SystemToggleIds.Id221 then
        GameUtils.BindRedPoint(Constants.RedPointConst.PhoneMessage, self.controller, true)
    elseif data.systemToggleId == Constants.SystemToggleIds.Id210 then
        GameUtils.BindRedPoint(Constants.RedPointConst.PhoneInvestigate, self.controller, true, Vector2(0, 41))
    elseif data.systemToggleId == Constants.SystemToggleIds.Id229 then
        GameUtils.BindRedPoint(Constants.RedPointConst.Friend, self.controller, true)
    end
end

function UIFeelingMainItemBtnNode:OnClick()
    if not self._data then
        return
    end
    if GameUtils.IsUnlockedBySystemTogId(self._data.systemToggleId) then
        if self._clickCb then
            self._clickCb()
        end
    else
        GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(self._data.systemToggleId))
    end
end

function UIFeelingMainItemBtnNode:OnDestroy()
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneAchievement)
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIFeelingMainItemBtnNode
